wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

// Days since 1970-01-01 -> (year, month, day), proleptic Gregorian.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch; the result is deliberately ignored so output is unchanged.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&tick.reason)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let now = crate::wasi::clocks::wall_clock::now();
        let (y, m, d) = civil_from_days((now.seconds / 86400) as i64);
        let y = y.clamp(0, 9999);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: now.seconds,
        }
    }
}

export!(Node);
